  gap: 11px;
  margin-top: 10px;
  padding: 12px;
  border: 1px solid #dce4dd;
  border-radius: 9px;
  background: #f0f4ef;
}

.link-preview > div {
  width: 32px;
  height: 32px;
  flex: none;
  display: grid;
  place-items: center;
  border-radius: 7px;
  color: #315c4b;
  background: #dce8df;
}

