const r = await tools.exec_command({cmd:"node --input-type=module <<'JS'
import { chromium } from '@playwright/test';
import fs from 'node:fs/promises';
const browser = await chromium.launch({headless:true, executablePath:'/opt/playwright-browsers/chromium-1228/chrome-linux64/chrome'});
const page = await browser.newPage({viewport:{width:1440,height:950}}); page.setDefaultTimeout(8000);
const errors=[]; page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
await page.goto('http://127.0.0.1:4000',{waitUntil:'networkidle'});
await page.evaluate(() => localStorage.clear()); await page.reload({waitUntil:'networkidle'});
await page.getByRole('button',{name:'Import & export'}).click();
await page.locator('input[type=file]').setInputFiles('/work/prototypes/sample-browser-bookmarks.html');
const result=await page.locator('.import-result.success').textContent();
const countAfterImport=await page.locator('.storage').textContent();
const downloadPromise=page.waitForEvent('download');
await page.getByRole('button',{name:/Export 10 bookmarks/}).click();
const download=await downloadPromise;
const path=await download.path(); const exported=await fs.readFile(path,'utf8');
const anchorCount=(exported.match(/<A HREF=/g)||[]).length;
const hasImportedTags=exported.includes('Space,Science,Research');
console.log(JSON.stringify({result,countAfterImport,anchorCount,hasImportedTags,filename:download.suggestedFilename(),errors}));
await browser.close();
